{
  "整体风格": "3D CG国漫番剧质感，都市赛博暗黑美学，冷蓝紫主调贯穿，猩红作为触发色点缀。材质上强调冷金属（不锈钢/碎玻璃）、湿沥青与脏污瓷砖的粗粝感，霓虹灯光在雨夜水洼中破碎晕染。光影以冷色霓虹为主光源，辅以昏黄顶灯与暖黄诊所灯光形成强烈冷暖对比，空气中浮着雨雾与玻璃碎屑微粒",
  "角色档案": [
    "沈秩，男，28岁，肤色苍白眼下乌青，黑发凌乱有几缕垂额，戴黑框眼镜（左镜腿刻着两道划痕），穿深灰连帽卫衣（帽子常半扣）、内搭褪色黑T恤、深蓝牛仔裤，脚蹬灰白运动鞋，手指修长但指节因紧张发白，气质清冷疲惫如穷途困兽",
    "季燃，女，26岁，肤白如瓷，纯黑长直发及腰，左眼角下一颗泪痣，穿白大褂内搭高领黑裙，脚穿黑色低跟短靴。左小臂缠绕猩红蛛网状裂纹，随救人次数的增加向肘部蔓延。气质温柔却暗藏疏离，如温柔殉道者",
    "魍像，外表与沈秩完全一致但嘴角裂至耳根，瞳孔纯黑无高光，面部有细碎玻璃纹路，穿与沈秩相同的深灰连帽卫衣但衣摆边缘呈破碎镜面状。存在形态不定，可寄居镜面/水面等反光平面。气质冰冷贪食如深渊凝视"
  ],
  "道具档案": [
    "破镜币，古铜色六边形硬币，正面阴刻一个『渡』字，反面阳刻『劫』字，边缘有细微磨损痕迹。以鲜血激活时币面会泛起暗红微光，可聚碎镜成盾，捏碎成粉末时可重置他人时间刻度，粉末呈金色荧光微粒",
    "血色倒计时纹，浮现于所有反光表面（镜面/水面/手机黑屏等）的血红色数字，正常状态下跳动递减，被魍像锁定时凝固为『00:00:00』后炸裂成雪花噪点，仅受术者本人可见",
    "镜之裂痕（季燃印记），缠绕在季燃左小臂上的猩红色蛛网状纹路，粗看如血管凸起，细看有细碎镜面反光，裂痕随治愈人数增加向心脏方向缓慢蔓延，纹路边缘有细小的玻璃碎屑脱落"
  ],
  "场景档案": [
    "深夜写字楼厕所，凌晨3:33，惨白灯管在头顶频闪发出嗡鸣，脚下是脏污的灰白瓷砖地砖缝隙发黑，三面墙上贴着剥落翘边的白色瓷砖，正对入口是一面沾满水渍的整墙洗手镜，洗手池不锈钢龙头在滴水，空气中飘散浓重消毒水与霉味混合的气味",
    "季燃心理诊所，暖黄台灯与冷白药柜顶灯形成强烈对冲，脚下是深棕色木地板，北墙一整面顶天立地药柜呈冷金属灰，柜中摆满大小不一的玻璃沙漏（所有沙漏的沙子都静止在中间位置），南窗模糊雨景如油画，书桌上摊开一本皮质笔记本，旁边立着一盏复古铜座台灯",
    "暴雨天桥与废弃橱窗，凌晨时分，湿漉漉的黑色沥青路面反射着两侧霓虹灯牌破碎的冷蓝紫光，天桥栏杆锈迹斑斑，桥下废弃商铺有一面巨大落地橱窗玻璃，玻璃表面布满蛛网状裂痕但尚未崩落，地面积水洼中漂着碎玻璃与烟蒂，空气湿冷带着铁锈与雨水气味"
  ],
  "分镜序列": [
    {
      "编号": 1,
      "标题": "深夜写字楼-厕所惊魂",
      "时间段": [
        "0-4s，特写洗手池镜面定帧。昏黄顶灯在头顶频闪发出嗡嗡低鸣，镜面蒙着薄薄一层水雾，水龙头滴下水珠在陶瓷池底溅开。沈秩的脸出现在镜中，黑框眼镜片映着惨白灯光，眼下乌青明显，他低头拧开水龙头，镜头跟随他双手在冷水下冲洗的动作，音效：水龙头拧开的金属嘎吱声，水流冲击池底的哗哗声，灯管频闪的电流嗡鸣",
        "4-7s，极速推近镜中倒影特写。沈秩关水抬头看向镜面，镜中倒影左上角突然浮现血色数字『00:03:12』，数字剧烈跳动后狂闪变成『00:00:00』，紧接着炸成满屏雪花噪点。在噪点消散的刹那，镜中的『他』嘴角向两侧缓缓咧开，瞳孔没有高光，笑容无声而扭曲。沈秩瞳孔骤然缩成针尖，嘴唇微张却发不出声音，音效：倒计时跳动时的电子嘀嗒声加速，炸裂成雪花噪点的静电爆裂声，镜中人咧嘴时玻璃摩擦般的细微咯吱声",
        "7-10s，中景沈秩踉跄后退。沈秩猛吸一口气向后踉跄，后背重重撞上身后隔间门板，门板发出闷响，他双手撑着身后门板大口喘气，黑框眼镜歪斜，额头冷汗顺着脸颊滑落，眼神死死盯着镜面不敢移开。镜中『沈秩』仍保持着那个裂到耳根的笑容，纹丝不动地凝视着他，音效：沈秩粗重的喘息声与心跳声，后背撞击门板的沉闷咚声，远处走廊传来空旷的风声"
      ]
    },
    {
      "编号": 2,
      "标题": "心理诊所-破镜之约",
      "时间段": [
        "0-4s，中景沈秩闯入诊所。沈秩猛地推开心理诊所玻璃门冲进来，镜头上移，暖黄台灯光线铺满画面，沈秩双手撑上季燃办公桌，桌面水杯被震翻，褐色的水在木纹桌面上蔓延，沈秩胸口起伏面色苍白，黑框眼镜下双眼布满血丝。音效：玻璃门被猛推开的哐当声，水杯倾倒撞击桌面的脆响，沈秩急促的喘息声",
        "4-7s，近景正反打季燃。季燃平静地端坐在办公桌对面，暖黄侧光打在左脸泪痣上，她垂眸从抽屉中取出一枚古铜色六边形硬币，硬币在她指间翻转，『渡』字面朝上。她用硬币边缘划破右手指腹，一滴暗红血珠渗出，滴入沈秩面前的白色咖啡杯里，在褐色液面上晕开。季燃抬眼直视沈秩，眼神冷静中透着一丝疲惫，音效：硬币在桌面轻叩的金属叮声，硬币边缘划破皮肤的微小声响，血珠滴入咖啡的嗒声",
        "7-10s，特写沈秩仰头饮尽。沈秩端起咖啡杯凑到唇边，镜头聚焦他喉结滚动，温热咖啡与血腥味混在一起被他吞下。画面边缘从四角开始渗入紫黑色雾气，雾气如触须般向画面中央蔓延，季燃的侧脸在雾后逐渐模糊。沈秩放下空杯，杯底与木桌磕出轻响，音效：沈秩吞咽时的咕噜声，杯子放桌的磕碰声，紫黑雾气弥漫的低频嗡鸣"
      ]
    },
    {
      "编号": 3,
      "标题": "暴雨天桥-倒影围城",
      "时间段": [
        "0-4s，俯拍旋转大全景。镜头从天桥正上方旋转俯拍，暴雨如鞭抽打在黑色沥青桥面上，两侧霓虹灯牌在雨幕中晕成模糊的冷蓝紫色光团，沈秩撑着一把黑伞独自走在桥面中央，黑伞在倾盆雨中微微摇晃。桥面上无数个积水洼在俯拍镜头里如碎裂镜面散布，每一个水洼中都倒映着沈秩撑伞的小小人形。音效：倾盆暴雨砸在伞面和桥面上的密集噼啪声，远处沉闷的雷声滚滚",
        "4-7s，极缓推近积水洼特写。镜头从全景缓缓推到桥面最近一处水洼，水洼表面因雨点击打泛着涟漪，倒影中的『沈秩』突然停止了走动，那个倒影没有撑伞，浑身被雨淋透，它齐刷刷和其他水洼中的倒影一同仰起头，无瞳孔的眼睛直直望向镜头方向。沈秩撑伞的脚步骤然停在画面外，镜头切至沈秩低头看向脚下水洼的视点镜头，音效：雨声在倒影抬头的瞬间骤然静止，只剩水滴从伞骨滑落的嘀嗒声，沈秩的呼吸声加重",
        "7-10s，近景沈秩猛回头。水洼中倒影缓缓抬起手臂，湿淋淋的手指从水面伸出，指向沈秩身后。沈秩瞳孔猛缩猛地拧身回头，黑伞在旋转中脱手飞出，伞面在暴雨中旋转划出一道弧线，慢动作下黑色伞骨与倾盆雨线交织。桥面空无一人，只有霓虹灯光在雨幕中无声闪烁，音效：沈秩猛转身时衣料摩擦的窸窣声，雨伞脱手旋转的风声，沈秩压低的喘息声『它来了』"
      ]
    },
    {
      "编号": 4,
      "标题": "废弃橱窗-碎镜之盾",
      "时间段": [
        "0-4s，中景橱窗玻璃碎裂。镜头跟随旋转的黑伞，黑伞边缘撞向天桥旁废弃商铺的巨大落地橱窗，伞骨撞击玻璃中心，整面玻璃瞬间炸开蛛网状裂纹但未崩落，裂纹从中心向四周呈放射状蔓延。沈秩因回头动作惯性跌坐在湿淋淋的桥面上，仰头望着碎裂的橱窗，音效：黑伞撞击玻璃的爆裂脆响，蛛网裂纹扩散时细密碎冰般的咯吱声，沈秩跌坐在地的闷响与痛哼",
        "4-8s，慢镜头侧拍季燃破窗。季燃从橱窗内部阴影中踏出，逆光的剪影在白大褂边缘镀上冷蓝紫霓虹光，她赤手握拳直直砸向蛛网裂纹中心，整面碎玻璃在慢动作中如蝴蝶般朝外翻飞、炸裂，碎屑在空中悬停逆飞形成一道旋转的碎镜屏障。屏障后方，一只由玻璃碎片拼凑成的人脸婴孩形状的怪物扭曲嘶吼，被屏障弹回碎镜深处，玻璃摩擦的尖啸撕裂夜空，音效：季燃拳砸玻璃的闷响与碎玻璃的哗啦炸裂声，碎镜逆飞的尖啸风切声，魍像发出玻璃刮擦般刺耳尖叫",
        "8-10s，近景季燃跪地露印。碎镜屏障消散，季燃膝盖落地跪在碎玻璃碴上，她低头喘息，右手指节渗血。她缓慢撩开左袖白大褂，小臂内侧的猩红蛛网状裂纹在冷光下清晰浮现，原本只到腕部的裂纹已蔓延至肘部，裂纹在霓虹光下微微反光如活物蠕动。季燃咬住下唇压下痛呼，音效：季燃双膝跪地的玻璃碎碴被压碎的细响，她压抑的低喘声，远处警笛声隐约从雨幕中传来"
      ]
    },
    {
      "编号": 5,
      "标题": "天桥之上-重置之价",
      "时间段": [
        "0-4s，近景沈秩扶住季燃。沈秩连滚带爬冲到季燃面前蹲下，双手扶住她肩膀，他脸上混合着震惊与困惑，雨水顺着凌乱发丝淌过镜片。季燃跪在碎玻璃中仰起惨白的脸，扯出一丝虚弱的笑，她缓缓摊开掌心，那枚古铜色破镜币已在拳握中碎裂成金色粉末，粉末从指缝中溢出。音效：沈秩急促的脚步声踩碎玻璃碴的脆响，他蹲下时衣料摩擦声，季燃微弱的呼气声",
        "4-7s，特写沈秩额间金色刻度。季燃将掌中金色粉末朝沈秩额头吹去，粉末如萤火般飘向沈秩额心，触及皮肤的瞬间融成一道金色刻度纹。沈秩的黑框眼镜镜片上映着金色刻度光的倒影，他红着眼眶揪住季燃白大褂衣领，嗓音嘶哑，额头青筋凸起，沈秩说：『你在用自己的命换我的命？你到底是谁！』（口音：普通话带轻微南方尾音，语速：急促爆发，情绪：嘶哑怒吼中带着恐惧）。音效：金色粉末飘散的细微沙沙声，沈秩揪衣领的布料绷紧声，他嘶吼时的颤抖气息",
        "7-10s，近景季燃惨笑回应。季燃被揪着衣领没有挣扎，反而轻轻歪头，雨水混着泪痣旁滑落的水珠划过脸颊，她声音虚弱却带着一丝释然的轻颤，季燃说：『一个……欠了太多时间债的骗子。』（口音：普通话标准偏慢，语速：极缓，情绪：虚弱苦笑）。她话音落下，沈秩额间的金色刻度纹开始跳动『72:00:00』，倒计时重新走动。音效：季燃虚弱的气声在雨夜里几乎被风吹散，沈秩怔住后倒抽一口冷气，远处霓虹灯牌电流滋滋声"
      ]
    },
    {
      "编号": 6,
      "标题": "后视镜中-倒影之刃",
      "时间段": [
        "0-5s，极限慢动作中景沈秩转头。沈秩听到季燃的话后怔在原地，雨水砸在他后背肩胛骨位置缓缓滑落。他像是被某种直觉牵引，极缓地转头望向旁边一辆熄火轿车的黑色后视镜。慢动作下每一滴雨水都在空中凝滞，霓虹灯光在水珠中折射成微型冷蓝紫色光斑。沈秩脸上的血色一寸寸褪尽，从茫然变为极度恐惧，喉结缓缓滚动却发不出声音。音效：慢动作下放大的雨滴坠落声如鼓点般沉重，远处雷声被拉成低频长鸣，沈秩倒抽的凉气被拉长成细丝般的嘶声",
        "5-10s，极推特写后视镜倒影与反打。黑色后视镜中倒映着季燃跪地的背影，但倒影中的『季燃』并未跟随她本尊跪地的动作——倒影笔直站立，双手交叠在腹前，嘴角噙着温柔的微笑，泪痣在镜面中清晰可辨。但那双手分明攥着一把尖利的碎玻璃锥，锥尖不偏不倚对准镜外季燃本尊的后心位置。沈秩的瞳孔放大到极致，黑框眼镜下双唇颤抖，他张开嘴却只有无声的气息从喉咙挤出。镜头切至沈秩极度惊恐的面部特写，又切回后视镜，倒影中的『季燃』歪了歪头，露出与魍像如出一辙的无瞳孔微笑，音效：心跳声如擂鼓被放大，碎玻璃锥尖在镜面光晕中折射出一声极细的金属颤鸣，沈秩无声张嘴时气息从牙缝挤出的嘶嘶声，黑屏后浮现血色小字『你的镜中，住着谁？』"
      ]
    }
  ]
}
